const SQL_KEYWORDS=new Set('SELECT FROM WHERE INSERT INTO VALUES UPDATE SET DELETE CREATE TABLE SCHEMA DATABASE ALTER DROP JOIN LEFT RIGHT INNER OUTER ON AS AND OR NOT NULL PRIMARY KEY FOREIGN REFERENCES INDEX VIEW PROCEDURE FUNCTION TRIGGER GROUP BY ORDER HAVING LIMIT OFFSET DISTINCT UNION ALL CASE WHEN THEN ELSE END IS LIKE IN EXISTS BETWEEN ASC DESC USE SHOW DESCRIBE EXPLAIN COMMIT ROLLBACK START TRANSACTION CALL'.split(' '));
function syntaxSql(line){
  const comment=line.indexOf('--'); let code=comment>=0?line.slice(0,comment):line,com=comment>=0?line.slice(comment):'';
  let out='',i=0;
  while(i<code.length){
    const ch=code[i];
    if(ch==='\''||ch==='"'||ch==='`'){const q=ch;let j=i+1;while(j<code.length){if(code[j]===q){if(code[j+1]===q){j+=2;continue}j++;break}if(code[j]==='\\')j+=2;else j++}out+='<span class="str">'+esc(code.slice(i,j))+'</span>';i=j;continue}
    if(/[A-Za-z_]/.test(ch)){let j=i+1;while(j<code.length&&/[A-Za-z0-9_$]/.test(code[j]))j++;const w=code.slice(i,j);out+=(SQL_KEYWORDS.has(w.toUpperCase())?'<span class="kw">'+esc(w)+'</span>':'<span class="ident">'+esc(w)+'</span>');i=j;continue}
    if(/[0-9]/.test(ch)){let j=i+1;while(j<code.length&&/[0-9.eE+-]/.test(code[j]))j++;out+='<span class="num">'+esc(code.slice(i,j))+'</span>';i=j;continue}
    out+=esc(ch);i++;
  }
  if(com)out+='<span class="com">'+esc(com)+'</span>';return out;
}
