function renderQueryTabs(){refs.queryTabs.innerHTML='';queryTabs.forEach(q=>{const t=document.createElement('div');t.className='qtab'+(q.id===activeQueryId?' active':'')+(q.dirty?' isDirty':'');t.dataset.id=q.id;const title=document.createElement('span');title.textContent=tabTitle(q);const dirty=document.createElement('span');dirty.className='dirty';dirty.textContent='●';const close=document.createElement('span');close.className='qclose';close.textContent='×';close.onclick=e=>{e.stopPropagation();closeQueryTab(q.id,true)};t.append(title,dirty,close);t.onclick=()=>{activeQueryId=q.id;currentSqlRange=null;renderQueryTabs();renderSql()};refs.queryTabs.appendChild(t)})}
