function helpFor(w){const x=String(w).toUpperCase();const map={SELECT:'SELECT column_list\nFROM table_name\nWHERE condition;',INSERT:'INSERT INTO table_name (columns)\nVALUES (values);',UPDATE:'UPDATE table_name\nSET column = value\nWHERE condition;',DELETE:'DELETE FROM table_name\nWHERE condition;',CREATE:'CREATE TABLE table_name (...);',ALTER:'ALTER TABLE table_name ...;',JOIN:'SELECT ...\nFROM a\nJOIN b ON a.id = b.id;'};return map[x]||'Use SQL statements to work with the active MySQL schema.'}
