function renderOutput(){const table=document.createElement('table');table.className='outputTable';table.innerHTML='<thead><tr><th></th><th>Time</th><th>Action</th><th>Message / SQL</th><th>Response</th><th>Duration / Fetch</th></tr></thead>';const tb=document.createElement('tbody');outputs.forEach((o,i)=>{const tr=document.createElement('tr');tr.dataset.output=i;tr.innerHTML='<td class="'+(o.status==='error'?'bad':o.status==='warning'?'warn':'ok')+'">'+(o.status==='error'?'✕':o.status==='warning'?'!':'✓')+'</td><td>'+esc(o.time||'')+'</td><td>'+esc(o.action||'Query')+'</td><td title="'+esc(o.sql||o.message||'')+'">'+esc((o.sql||o.message||'').slice(0,100))+'</td><td>'+esc(o.response||'OK')+'</td><td>'+esc(o.duration||'0.000 sec')+'</td>';tr.oncontextmenu=e=>{e.preventDefault();showContextMenu(e.clientX,e.clientY,[['Append Selected Items to SQL Script',()=>reuseOutput(i,'append')],['Replace SQL Script with Selected Items',()=>reuseOutput(i,'replace')]])};tb.appendChild(tr)});table.appendChild(tb);refs.bottomBody.appendChild(table)}
function renderResult(){const r=results.find(x=>x.id===activeResultId)||results[results.length-1];if(!r){refs.bottomBody.innerHTML='<div style="padding:9px;color:var(--muted)">No result set.</div>';return}const tool=document.createElement('div');tool.className='resultToolbar';const apply=document.createElement('button');apply.textContent='Apply';apply.disabled=readOnlyResult||!dirtyCells.size;apply.onclick=applyGridChanges;const revert=document.createElement('button');revert.textContent='Revert';revert.disabled=readOnlyResult||!dirtyCells.size;revert.onclick=revertGridChanges;const add=document.createElement('button');add.textContent='+ Row';add.disabled=readOnlyResult;add.onclick=()=>addResultRow({});const del=document.createElement('button');del.textContent='− Row';del.disabled=readOnlyResult;del.onclick=()=>deleteResultRow({row:selectedCell?Number(selectedCell.split(':')[0]):(r.rows?.length||1)-1});const exp=document.createElement('button');exp.textContent='Export';exp.onclick=()=>showExportWizard({result:r});const pin=document.createElement('button');pin.textContent=r.pinned?'Unpin':'Pin';pin.onclick=()=>{r.pinned=!r.pinned;renderBottom()};const close=document.createElement('button');close.textContent='Close';close.onclick=()=>closeResult(r.id);tool.append(apply,revert,add,del,exp,pin,close);const ro=document.createElement('span');ro.className='readOnly';ro.textContent=readOnlyResult?'🔒 Read Only':'Editable Result';tool.appendChild(ro);refs.bottomBody.appendChild(tool);if(resultFilter||resultSort){const info=document.createElement('div');info.className='resultFilterInfo';info.textContent=[resultFilter?('Filter: '+resultFilter):'',resultSort?('Sort: '+resultSort.column+' '+resultSort.direction):''].filter(Boolean).join('   ');refs.bottomBody.appendChild(info)}const wrap=document.createElement('div');wrap.className='gridWrap';const table=document.createElement('table');table.className='resultGrid';const cols=r.columns||Object.keys(r.rows?.[0]||{});const thead=document.createElement('thead');thead.innerHTML='<tr><th class="rownum">#</th>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr>';table.appendChild(thead);const tb=document.createElement('tbody');let displayRows=(r.rows||[]).map((row,ri)=>({row,ri}));if(resultFilter){const f=resultFilter.toLowerCase();displayRows=displayRows.filter(x=>Object.values(x.row||{}).some(v=>String(v??'').toLowerCase().includes(f)))}if(resultSort){const c=resultSort.column,dir=resultSort.direction==='desc'?-1:1;displayRows.sort((a,b)=>String(a.row?.[c]??'').localeCompare(String(b.row?.[c]??''),undefined,{numeric:true})*dir)}displayRows.forEach(({row,ri})=>{const tr=document.createElement('tr');const rn=document.createElement('td');rn.className='rownum';rn.textContent=ri+1;tr.appendChild(rn);cols.forEach((c,ci)=>{const td=document.createElement('td');const key=ri+':'+ci;td.textContent=row[c]??'';td.dataset.row=ri;td.dataset.col=ci;td.contentEditable=readOnlyResult?'false':'true';if(dirtyCells.has(key))td.classList.add('changed');if(selectedCell===key)td.classList.add('selected');td.onclick=()=>{selectedCell=key;renderBottom()};td.oninput=()=>{dirtyCells.set(key,td.textContent);apply.disabled=false;revert.disabled=false;td.classList.add('changed')};tr.appendChild(td)});tb.appendChild(tr)});table.appendChild(tb);wrap.appendChild(table);refs.bottomBody.appendChild(wrap)}
function setBottomMode(mode){bottomMode=mode==='results'?'results':'output';document.querySelectorAll('.bottomTab').forEach(t=>t.classList.toggle('active',t.dataset.bottom===bottomMode));renderBottom()}
function addOutput(o={}){outputs.push({status:o.status||'success',time:o.time||deterministicTime(),action:o.action||'Query',sql:o.sql||'',message:o.message||'',response:o.response||'OK',duration:o.duration||'0.001 sec'});if(outputs.length>200)outputs.shift();setBottomMode('output')}
function addResult(r={}){const id=r.id||nextId('result');const item={id,title:r.title||'Result Grid',columns:r.columns||Object.keys(r.rows?.[0]||{}),rows:deepClone(r.rows||[]),pinned:!!r.pinned,editable:r.editable!==false};results.push(item);activeResultId=id;readOnlyResult=!item.editable;dirtyCells.clear();setBottomMode('results')}
function closeResult(id){results=results.filter(r=>r.id!==id);activeResultId=results.at(-1)?.id||null;dirtyCells.clear();renderBottom()}
function applyGridChanges(){const r=results.find(x=>x.id===activeResultId);if(!r||readOnlyResult)return;const cols=r.columns||Object.keys(r.rows?.[0]||{});for(const [key,val] of dirtyCells){const [ri,ci]=key.split(':').map(Number);if(r.rows[ri])r.rows[ri][cols[ci]]=val}dirtyCells.clear();stagedTransaction=!autoCommit;addOutput({action:'Apply Result Changes',message:'Result grid changes applied',response:autoCommit?'Committed':'Pending commit'});notify(autoCommit?'Changes applied and committed':'Changes applied; commit pending')}
