function currentResult(){return results.find(x=>x.id===activeResultId)||results.at(-1)||null}
function duplicateSQLTab(d={}){const q=currentQuery();if(!q)return;const copy={...deepClone(q),id:d.id||nextId('sql'),title:d.title||q.title+' Copy',dirty:true};queryTabs.push(copy);activeQueryId=copy.id;renderQueryTabs();renderSql();status('SQL tab duplicated')}
function renameSQLTab(d={}){const q=queryTabs.find(x=>x.id===(d.id||activeQueryId));if(q){q.title=d.title||d.name||q.title;q.dirty=true;renderQueryTabs();status('SQL tab renamed')}}
function addResultRow(d={}){const r=currentResult();if(!r||readOnlyResult)return;const cols=r.columns||Object.keys(r.rows?.[0]||{});const row=d.row||Object.fromEntries(cols.map(c=>[c,d.values?.[c]??'']));r.rows=r.rows||[];r.rows.push(row);stagedTransaction=!autoCommit;renderBottom();status('Result row added')}
function deleteResultRow(d={}){const r=currentResult();if(!r||readOnlyResult||!r.rows?.length)return;const ri=Math.max(0,Math.min(r.rows.length-1,Number(d.row??r.rows.length-1)));r.rows.splice(ri,1);selectedCell=null;stagedTransaction=!autoCommit;renderBottom();status('Result row deleted')}
function renderExplain(d={},visual=false){const plan=d.plan||[{id:1,select_type:'SIMPLE',table:'survey_record',type:'range',key:'idx_lat_lon',rows:42,extra:'Using index condition'},{id:1,select_type:'SIMPLE',table:'survey_project',type:'eq_ref',key:'PRIMARY',rows:1,extra:''}];if(visual)showSurface('explain','Visual Explain',plan.map((p,i)=>`${i?'<div class="planArrow">↓</div>':''}<div class="planNode"><b>${esc(p.table)}</b><br>Access: ${esc(p.type)} &nbsp; Key: ${esc(p.key||'—')} &nbsp; Rows: ${esc(p.rows)}</div>`).join(''));else showSurface('explain','EXPLAIN Query','<table class="eduTable"><tr><th>select_type</th><th>table</th><th>type</th><th>key</th><th>rows</th><th>Extra</th></tr>'+plan.map(p=>`<tr><td>${esc(p.select_type)}</td><td>${esc(p.table)}</td><td>${esc(p.type)}</td><td>${esc(p.key||'')}</td><td>${esc(p.rows)}</td><td>${esc(p.extra||'')}</td></tr>`).join('')+'</table>')}
function renderQueryStats(d={}){const s=d.stats||{duration:'0.014 sec',rowsExamined:128,rowsReturned:12,tempTables:0,sortMergePasses:0};showSurface('explain','Query Statistics','<div class="eduGrid">'+Object.entries(s).map(([k,v])=>card(k,'<div class="eduMetric">'+esc(v)+'</div>')).join('')+'</div>')}
function renderProfiler(d={}){const stages=d.stages||[{name:'Starting',pct:4},{name:'Optimizing',pct:8},{name:'Executing',pct:68},{name:'Sending data',pct:20}];showSurface('performance','Query Profiler',stages.map(x=>`<div>${esc(x.name)} ${esc(x.pct)}%</div><div class="profileBar"><div class="profileFill" style="width:${Number(x.pct)||0}%"></div></div>`).join(''))}
function objectDdl(n){if(!n)return '-- No object selected';if(n.ddl)return n.ddl;const full='`'+(activeSchema||'schema')+'`.`'+(n.name||'object')+'`';if(n.type==='table')return `CREATE TABLE ${full} (...);`;if(n.type==='view')return `CREATE VIEW ${full} AS SELECT ...;`;if(n.type==='procedure')return `CREATE PROCEDURE ${full}() BEGIN END;`;if(n.type==='function')return `CREATE FUNCTION ${full}() RETURNS INT RETURN 1;`;return `-- DDL for ${n.type||'object'} ${full}`}
function showDdl(d={}){const n=findNode(tree,d.path||selectedPath);showSurface(d.mode||'schemaInspector','Object DDL','<pre class="helpCode">'+esc(d.ddl||objectDdl(n))+'</pre>')}
function countTreeType(nodes,type){let n=0;for(const x of nodes||[]){if(x.type===type)n++;n+=countTreeType(x.children,type)}return n}
function renderSchemaInspector(d={}){const schema=d.schema||activeSchema||tree.find(n=>n.type==='schema')?.name||'schema';const tables=d.tables??countTreeType(tree,'table'),views=d.views??countTreeType(tree,'view'),routines=d.routines??(countTreeType(tree,'procedure')+countTreeType(tree,'function'));showSurface('schemaInspector','Schema Inspector — '+schema,'<div class="eduGrid">'+card('Tables','<div class="eduMetric">'+tables+'</div>')+card('Views','<div class="eduMetric">'+views+'</div>')+card('Routines','<div class="eduMetric">'+routines+'</div>')+card('Default Charset','<div class="eduMetric">'+esc(d.charset||'utf8mb4')+'</div>')+'</div>')}
function renderTableInspector(d={}){const n=findNode(tree,d.path||selectedPath)||{name:d.name||'table',properties:{}};const p={Engine:'InnoDB',Rows:d.rows??n.properties?.Rows??1000,'Data Length':d.dataLength||'128 KiB','Index Length':d.indexLength||'64 KiB','Auto Increment':d.autoIncrement||'1001',...n.properties};showSurface('tableInspector','Table Inspector — '+(n.name||'table'),'<div class="eduGrid">'+Object.entries(p).map(([k,v])=>card(k,'<div class="eduMetric">'+esc(v)+'</div>')).join('')+'</div>')}
function findFolder(schemaName,name){const s=tree.find(n=>n.type==='schema'&&n.name===schemaName)||tree.find(n=>n.type==='schema');if(!s)return null;let f=(s.children||[]).find(n=>n.name===name);if(!f){f={name,type:'folder',path:(s.path||s.name)+'/'+name.toLowerCase().replace(/\s+/g,'_'),children:[]};s.children=(s.children||[]).concat(f)}return f}
function addTreeObject(folderName,obj){const f=findFolder(activeSchema,folderName);if(!f)return null;f.children=f.children||[];if(!f.children.some(x=>x.name===obj.name))f.children.push(obj);treeOpen.set(f.path,true);renderTree();return obj}
function removeNamedTreeObject(folderName,name){const f=findFolder(activeSchema,folderName);if(f)f.children=(f.children||[]).filter(x=>x.name!==name);renderTree()}
