function renderLogs(d={}){const logs=d.logs||[{time:'00:00:01',level:'System',message:'mysqld ready for connections'},{time:'00:00:05',level:'Warning',message:'Example educational warning'}];showSurface('server','Server Logs','<table class="eduTable"><tr><th>Time</th><th>Level</th><th>Message</th></tr>'+logs.map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.level)}</td><td>${esc(x.message)}</td></tr>`).join('')+'</table>')}
