 showSurface('model','EER Diagram — '+(modelState.name||'Model'),'<div class="eerShell"><div class="eerToolbar"><button>↖ Select</button><button>▦ Add Table</button><button>1:N Relationship</button><button>N:M Relationship</button><button>Layer</button><button>Note</button><span class="grow"></span><button>−</button><b>'+esc(modelState.zoom||100)+'%</b><button>＋</button></div><div class="eerMain"><aside class="eerPalette"><b>Catalog Tree</b>'+tables.map(t=>'<div>▦ '+esc(t.name)+'</div>').join('')+'<hr><b>Layers</b><div>Main Diagram</div><hr><b>Properties</b><div>Engine: InnoDB</div><div>Charset: utf8mb4</div></aside><div class="eerCanvas">'+cards+lines+'</div></div></div>');
