function collectModelTables(){const out=[];function walk(list){for(const n of list||[]){if(n.type==='table')out.push({name:n.name,columns:((n.children||[]).find(x=>x.name==='Columns')?.children||[]).map(c=>`${c.name} ${c.properties?.Datatype||''}`)});walk(n.children)}}walk(tree);return out}
function collectDictionary(){const out=[];function walk(list,schema=''){for(const n of list||[]){const s=n.type==='schema'?n.name:schema;if(['table','view','procedure','function','trigger'].includes(n.type))out.push({schema:s,name:n.name,type:n.type,comment:n.properties?.Comment||''});walk(n.children,s)}}walk(tree);return out}

