 preferencesPage=page||preferencesPage;const pages=['General Editors','SQL Editor','Administration','Modeling','Fonts & Colors','SSH'];
 showSurface('preferences','Preferences','<div class="preferencesShell"><aside>'+pages.map(x=>'<div class="'+(x===preferencesPage?'active':'')+'" data-pref-page="'+esc(x)+'">'+esc(x)+'</div>').join('')+'</aside><section><h2>'+esc(preferencesPage)+'</h2>'+(preferencesPage==='SQL Editor'?'<div class="nativePage"><label><input type="checkbox" checked> Safe Updates</label><label><input type="checkbox" checked> Show schema names in object browser</label><label><input type="checkbox" checked> Enable Code Completion</label><div class="formGrid"><label>DBMS connection read timeout</label><input value="30"><label>Limit Rows</label><input value="'+esc(rowLimit)+'"></div></div>':preferencesPage==='Modeling'?'<div class="nativePage"><label><input type="checkbox" checked> Place new objects on active diagram</label><label><input type="checkbox" checked> Use global font settings</label><div class="formGrid"><label>Default Storage Engine</label><select><option>InnoDB</option></select><label>Default Charset</label><select><option>utf8mb4</option></select></div></div>':'<div class="nativePage"><label><input type="checkbox" checked> Enable default Workbench behavior</label><div class="formGrid"><label>Theme</label><select><option>System</option><option>Dark</option></select><label>Font</label><input value="Segoe UI 10"></div></div>')+'<div class="editorActions"><button>Cancel</button><button class="primary">Apply</button></div></section></div>');
 setTimeout(()=>document.querySelectorAll('[data-pref-page]').forEach(x=>x.onclick=()=>renderPreferences(x.dataset.prefPage)),0);
