function renderServiceControl(){showSurface('server','Startup / Shutdown','<div class="serviceControl"><div class="serviceHero"><span class="serverState '+(serverRunning?'':'off')+'">'+(serverRunning?'RUNNING':'STOPPED')+'</span><h2>MySQL80</h2><p>Windows Service • localhost</p><div><button>Start Server</button><button>Stop Server</button></div></div><div><h3>Startup Message Log</h3><pre>MySQL Community Server - GPL\nServer initialized\nready for connections</pre></div></div>')}
function setActiveSchema(name){activeSchema=name;updateConnectionChrome();renderTree();addOutput({action:'Schema',message:'USE `'+name+'`',response:'Default schema changed'});status('Active schema: '+name)}
function refreshSchemas(){renderTree();addOutput({action:'Refresh',message:'Schema metadata refreshed',response:'OK'});notify('Schemas refreshed')}
function generateSqlFromObject(n,type,run){const name='`'+(activeSchema?activeSchema+'`.`':'')+String(n.name||'table')+'`';const cols=(n.children||[]).find(x=>x.name==='Columns')?.children?.map(x=>'`'+x.name+'`')||['*'];let sql='';switch(type){case'select':sql='SELECT '+(cols.length?cols.join(', '):'*')+'\nFROM '+name+'\nLIMIT 1000;';break;case'insert':sql='INSERT INTO '+name+' ('+cols.join(', ')+')\nVALUES ('+cols.map(()=>'?').join(', ')+');';break;case'update':sql='UPDATE '+name+'\nSET '+(cols[0]||'`column`')+' = ?\nWHERE /* condition */;';break;case'delete':sql='DELETE FROM '+name+'\nWHERE /* condition */;';break;case'create':sql=n.ddl||('CREATE TABLE '+name+' (\n  `id` INT NOT NULL,\n  PRIMARY KEY (`id`)\n);');break}const q=currentQuery();if(q){q.sql=(q.sql?q.sql+'\n\n':'')+sql;q.dirty=true;renderQueryTabs();renderSql()}addOutput({action:'Generate SQL',sql,response:'SQL generated'});if(run)executeSql({sql,result:n.sampleResult||{columns:cols.map(c=>c.replace(/`/g,'')),rows:[],editable:true}})}
function beautify(sql){return String(sql||'').replace(/\s+/g,' ').replace(/\b(SELECT|FROM|WHERE|GROUP BY|ORDER BY|HAVING|LIMIT|VALUES|SET|JOIN|LEFT JOIN|RIGHT JOIN|INNER JOIN)\b/gi,'\n$1').replace(/^\n/,'').replace(/,\s*/g,',\n  ').replace(/\b(SELECT|INSERT INTO|UPDATE|DELETE FROM|CREATE TABLE)\b/i,m=>m.toUpperCase()).trim()}
function beautifyCurrent(){const q=currentQuery();if(!q)return;q.sql=beautify(q.sql);q.dirty=true;renderSql();renderQueryTabs();addOutput({action:'Beautify',message:'SQL formatted',response:'OK'})}
function keywordCase(mode){const q=currentQuery();if(!q)return;q.sql=q.sql.replace(/\b[A-Za-z_]+\b/g,w=>SQL_KEYWORDS.has(w.toUpperCase())?(mode==='lower'?w.toLowerCase():w.toUpperCase()):w);q.dirty=true;renderSql();renderQueryTabs()}
function insertSnippet(sn){const q=currentQuery();if(!q)return;q.sql+=(q.sql?'\n':'')+sn.sql;q.dirty=true;renderSql();renderQueryTabs();status('Snippet inserted')}
function replaceWithSnippet(sn){const q=currentQuery();if(!q)return;q.sql=sn.sql;q.dirty=true;renderSql();renderQueryTabs();status('SQL replaced with snippet')}
function copySnippet(sn){navigator.clipboard?.writeText(sn.sql).catch(()=>{});notify('Snippet copied')}
function saveSnippet(data={}){const q=currentQuery();const sn={id:data.id||nextId('sn'),name:data.name||('Snippet '+(snippets.length+1)),sql:data.sql??q?.sql??''};snippets.push(sn);setRightMode('snippets');notify('Snippet saved')}
function reuseOutput(i,mode){const o=outputs[i],sql=o?.sql||o?.message||'';const q=currentQuery();if(!q||!sql)return;q.sql=mode==='replace'?sql:(q.sql?q.sql+'\n'+sql:sql);q.dirty=true;renderSql();renderQueryTabs();status(mode==='replace'?'SQL replaced from Action Output':'SQL appended from Action Output')}
function executeSql(d={}){const q=currentQuery();const sql=d.sql??q?.sql??'';if(!sql.trim()){addOutput({status:'warning',action:'Query',message:'No SQL to execute',response:'No statement'});return}if(d.error){addOutput({status:'error',action:'Query',sql,response:d.error,duration:d.duration||'0.002 sec'});notify(d.error,'error');return}addOutput({action:d.action||'Query',sql,response:d.response||((d.affectedRows!=null)?d.affectedRows+' row(s) affected':'OK'),duration:d.duration||'0.003 sec'});if(d.result)addResult(d.result);if(/\b(INSERT|UPDATE|DELETE|CREATE|ALTER|DROP)\b/i.test(sql))stagedTransaction=!autoCommit;status('Query executed')}
function executeCurrent(d={}){executeSql(d)}
function executeAll(d={}){executeSql(d)}
function stopQuery(){addOutput({status:'warning',action:'Query',message:'Query execution stopped',response:'Cancelled'});notify('Query stopped','warning')}
function commit(){stagedTransaction=false;addOutput({action:'Transaction',message:'COMMIT',response:'Changes committed'});notify('Transaction committed')}
function rollback(){stagedTransaction=false;addOutput({action:'Transaction',message:'ROLLBACK',response:'Changes rolled back'});notify('Transaction rolled back')}

function renderConnections(){refs.connectionCards.innerHTML='';if(!connections.length)refs.connectionCards.innerHTML='<div style="color:var(--muted);font-size:10px">No saved connections. Click + to create one.</div>';connections.forEach(c=>{const card=document.createElement('div');card.className='connCard';card.dataset.connection=c.id;card.innerHTML='<div class="connName">'+esc(c.name)+'</div><div class="connMeta">'+esc(c.user||'root')+' @ '+esc(c.host||'localhost')+':'+esc(c.port||3306)+'<br>'+esc(c.schema||'No default schema')+'</div>';card.ondblclick=()=>connectTo(c.id);card.onclick=()=>{activeConnectionId=c.id;updateConnectionChrome()};card.oncontextmenu=e=>{e.preventDefault();showContextMenu(e.clientX,e.clientY,[['Open Connection',()=>connectTo(c.id)],['Edit Connection…',()=>showConnectionDialog(c)],['Duplicate Connection',()=>duplicateConnection(c.id)],['Delete Connection',()=>deleteConnection(c.id)]])};refs.connectionCards.appendChild(card)})}
function showHome(){refs.home.classList.add('show');renderConnections();renderHomeExtras();status('Home')}
function renderHomeExtras(){
 const models=document.getElementById('homeModels');if(models)models.innerHTML=(modelState.tables?.length?'<div class="homeModelCard"><b>'+esc(modelState.name||'Local Model')+'</b><span>'+modelState.tables.length+' tables • '+(modelState.relationships?.length||0)+' relationships</span></div>':'<div class="homeModelCard empty"><b>Create EER Model</b><span>Design database schemas visually</span></div>');
 const migration=document.getElementById('homeMigration');if(migration)migration.innerHTML='<div class="homeMigrationCard"><b>Database Migration</b><span>Move schemas and data from another RDBMS to MySQL</span><button id="homeMigrationBtn">Start Migration</button></div>';
 setTimeout(()=>{const b=document.getElementById('homeMigrationBtn');if(b)b.onclick=()=>renderMigration({})},0);
}
function hideHome(){refs.home.classList.remove('show')}
function connectTo(id){const c=connections.find(x=>x.id===id);if(!c)return;activeConnectionId=id;c.connected=true;activeSchema=c.schema||activeSchema||null;hideHome();updateConnectionChrome();addOutput({action:'Connection',message:'Connected to '+c.name,response:'Connection established'});notify('Connected to '+c.name)}
function disconnect(){const c=activeConnection();if(c)c.connected=false;connected=false;updateConnectionChrome();addOutput({action:'Connection',message:'Disconnected',response:'OK'})}
function addConnection(data){const c={id:data.id||nextId('conn'),name:data.name||'Local instance MySQL',host:data.host||'localhost',port:Number(data.port||3306),user:data.user||'root',schema:data.schema||'',storePassword:!!data.storePassword,connected:false};connections.push(c);renderConnections();return c}
function duplicateConnection(id){const c=connections.find(x=>x.id===id);if(!c)return;addConnection({...c,id:nextId('conn'),name:c.name+' Copy',connected:false});notify('Connection duplicated')}
