function createTable(data={}){const s=tree.find(n=>n.type==='schema'&&n.name===activeSchema)||tree.find(n=>n.type==='schema');if(!s){notify('Create or select a schema first','error');return}let tables=(s.children||[]).find(n=>n.name==='Tables');if(!tables){tables={name:'Tables',type:'folder',path:(s.path||s.name)+'/tables',children:[]};s.children=(s.children||[]).concat(tables)}const name=data.name||'new_table';tables.children.push({name,type:'table',path:tables.path+'/'+name,ddl:data.ddl,properties:{Engine:'InnoDB'},children:[{name:'Columns',type:'folder',path:tables.path+'/'+name+'/columns',children:[{name:'id',type:'column',path:tables.path+'/'+name+'/columns/id',properties:{Datatype:'INT',PK:'YES'}},{name:'name',type:'column',path:tables.path+'/'+name+'/columns/name',properties:{Datatype:'VARCHAR(100)'}}]},{name:'Indexes',type:'folder',path:tables.path+'/'+name+'/indexes',children:[]},{name:'Foreign Keys',type:'folder',path:tables.path+'/'+name+'/fks',children:[]},{name:'Triggers',type:'folder',path:tables.path+'/'+name+'/triggers',children:[]}]});treeOpen.set(tables.path,true);renderTree();addOutput({action:'Create Table',sql:data.ddl||('CREATE TABLE `'+name+'` ...'),response:'Table created'})}
