function showImportWizard(data={}){showModal('Table Data Import Wizard',`<div class="wizardSteps"><div class="wizardStep active">1 Source</div><div class="wizardStep">2 Destination</div><div class="wizardStep">3 Mapping</div><div class="wizardStep">4 Import</div></div><div class="formGrid"><label>Import File</label><input id="impFile" value="${esc(data.file||'C:\\data\\input.csv')}"><label>Destination Schema</label><input id="impSchema" value="${esc(data.schema||activeSchema||'')}"><label>Destination Table</label><input id="impTable" value="${esc(data.table||'imported_data')}"><label>Format</label><select><option>CSV</option><option>JSON</option></select></div>`,[{label:'Cancel',onClick:closeModal},{label:'Start Import',primary:true,onClick:()=>{closeModal();importData({file:$('impFile')?.value||data.file,table:$('impTable')?.value||data.table,rows:data.rows||100})}}])}
