function showExportWizard(data={}){showModal('Table Data Export Wizard',`<div class="wizardSteps"><div class="wizardStep active">1 Source</div><div class="wizardStep">2 Output</div><div class="wizardStep">3 Export</div></div><div class="formGrid"><label>Table / Result</label><input id="expSource" value="${esc(data.table||data.result?.title||'current_result')}"><label>Output File</label><input id="expFile" value="${esc(data.file||'C:\\data\\export.csv')}"><label>Format</label><select id="expFormat"><option>CSV</option><option>JSON</option><option>SQL INSERT</option></select></div>`,[{label:'Cancel',onClick:closeModal},{label:'Start Export',primary:true,onClick:()=>{const file=$('expFile').value;closeModal();exportData({file,rows:data.result?.rows?.length||data.rows||0})}}])}
