function openScript(data={}){const q=currentQuery()||ensureQuery('sql-1');q.title=data.title||data.filename||'script.sql';q.sql=data.sql||'';q.savedPath=data.path||data.filename||null;q.dirty=false;activeQueryId=q.id;renderQueryTabs();renderSql();addOutput({action:'Open Script',message:q.savedPath||q.title,response:'Opened'})}
function saveScript(data={}){const q=currentQuery();if(!q)return;q.savedPath=data.path||data.filename||q.savedPath||((q.title||'script').replace(/\s+/g,'_')+'.sql');q.title=data.title||q.savedPath.split(/[\\/]/).pop();q.dirty=false;renderQueryTabs();addOutput({action:'Save Script',message:q.savedPath,response:'Saved'});notify('SQL script saved')}
function setSql(d={}){const q=d.queryId?ensureQuery(d.queryId,d.title||'SQL File'):currentQuery();if(!q)return;q.sql=String(d.sql??'');q.dirty=d.dirty!==false;activeQueryId=q.id;currentSqlRange=null;renderQueryTabs();renderSql()}
function buildSqlInsertion(src,marker,sql,position='replace'){const lines=String(src||'').split('\n'),i=lines.findIndex(x=>x.includes(marker));if(i<0)return null;const ind=(lines[i].match(/^\s*/)||[''])[0],ins=String(sql||'').trimEnd().split('\n').map(x=>x?ind+x:'');let final,startLine;if(position==='before'){final=[...lines.slice(0,i),...ins,...lines.slice(i)];startLine=i+1}else if(position==='after'){final=[...lines.slice(0,i+1),...ins,...lines.slice(i+1)];startLine=i+2}else{final=[...lines.slice(0,i),...ins,...lines.slice(i+1)];startLine=i+1}return {text:final.join('\n'),startLine,endLine:startLine+Math.max(1,ins.length)-1}}
async function typeSql(d={},animate,token){const q=d.queryId?ensureQuery(d.queryId,d.title||'SQL File'):currentQuery();if(!q)return;activeQueryId=q.id;let built;if(d.marker)built=buildSqlInsertion(q.sql,d.marker,d.sql||'',['before','after','replace'].includes(d.position)?d.position:'replace');else{const startLine=String(q.sql||'').split('\n').length;built={text:d.append?(q.sql+(q.sql?'\n':'')+(d.sql||'')):(d.sql||''),startLine:d.append?startLine+1:1,endLine:(d.append?startLine:0)+String(d.sql||'').replace(/\r/g,'').trimEnd().split('\n').length}}if(!built){status('SQL marker not found');return}const final=built.text;if(!(animate&&autoType)){q.sql=final}else{const old=q.sql,chars=String(d.sql||''),steps=Math.min(Math.max(chars.length,1),60),dur=Math.min(1000,Math.max(240,chars.length*3));for(let i=1;i<=steps;i++){if(token!==seekToken)return;const part=chars.slice(0,Math.floor(chars.length*i/steps));if(d.marker){const b=buildSqlInsertion(old,d.marker,part,d.position||'replace');q.sql=b?.text||old}else q.sql=d.append?(old+(old?'\n':'')+part):part;renderSql();await sleep(dur/steps)}q.sql=final}q.dirty=true;currentSqlRange={query:q.id,startLine:built.startLine,endLine:built.endLine};renderQueryTabs();renderSql();return {...built,query:q.id}}

